from taf.internal.aliasing import aliasing_scope
from taf.ue.rpc.mtk.proxy import MTKProxy
from taf.ue.rpc.mtk.mtk_rpc import MTKRPC
from taf.internal.rpc.pyro import PYROKeyWords
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class mtk(PYROKeyWords):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='proxy',
                                           lookup_type=MTKProxy)

    def __init__(self):
        super(mtk, self).__init__()
        self._rpc = MTKRPC()

    def configure(self, hostname, port, username=None, password=None, server_dir=None, python_path=None):
        """
        configure the remote server settings

        :param str hostname:    remote server hostname e.g. ip address
        :param int port:   port no the remote server will listen on
        :param Optional[str] username: username for ssh connection to the pc the remote server will run on
        :param Optional[str] password: password for ssh connection to the pc the remote server will run on
        :param Optional[str] server_dir:  server working directory on remote server
        :param Optional[str] python_path: python path in the remote server
        :return: None
        """
        self._rpc.configure(hostname, port, username, password, server_dir, python_path)

    def setup(self):
        """"
        connect to remote server via ssh and transfer required server file(s) to the remote pc

        :return: None
        :raise RequiredSoftwareMissing: if python or pyro4 was not installed
        :raise ConnectFailedError: if ssh connecting failed, raise ConnectFailedError
        """
        self._rpc.setup()

    def teardown(self):
        """
        if server is still running will stop server first then disconnect ssh connection to the remote pc

        :return: None
        """
        self._rpc.teardown()

    def create_proxy(self, alias=None):
        """
        create proxy instance with  alias

        :param Optional[str] alias: proxy alias
        :return: proxy instance
        :rtype: taf.ue.rpc.mtk.proxy.Proxy
        """
        proxy = self._rpc.create_proxy()
        self.store.add(proxy, alias)
        return proxy

    @lookup_handler.implicit_lookup
    def connect_device(self, edb_file_path, com=None, proxy=None):
        """
        connect to mtk ue device

        :param str edb_file_path: absolute path of edb file on the remote server
        :param Optional[str] com:  com port identifier, if default, will select "auto"
        :param Optional[str] proxy: proxy alias
        :return: None
        """
        proxy.connect_device(edb_file_path, com)

    @lookup_handler.implicit_lookup
    def disconnect_device(self, proxy=None):
        """
        disconnect from ue mtk device

        :param Optional[str] proxy: proxy alias
        :return: None
        """
        proxy.disconnect_device()

    @lookup_handler.implicit_lookup
    def get_platform_information(self, proxy=None):
        """
        get the software platform information of the mtk ue device

        :param Optional[str] proxy: proxy alias
        :return: platform information
        :rtype: dict
        """
        return proxy.get_platform_information()

    @lookup_handler.implicit_lookup
    def is_com_ports_ready(self, port_names=None, proxy=None):
        """
        check if the ports already ready after reboot or plugged in

        :param Optional[tuple] port_names: port names need to be checked
        :param Optional[str] proxy: proxy alias
        :return: True or False
        :rtype: bool
        """
        return proxy.is_com_ports_ready(port_names)

    @lookup_handler.implicit_lookup
    def set_filter(self, filter_name=None, proxy=None):
        """
        set logger filter to enable ota, system trace ... logging enable

        :param Optional[str] filter_name:  if default will be "2.Gen97_Default_Standard"
        :param Optional[str] proxy: proxy alias
        :return: None
        """
        proxy.set_filter(filter_name=filter_name)

    @lookup_handler.implicit_lookup
    def save_elg_log(self, output_path, proxy=None):
        """
        save elg log

        :param str output_path:  elg output path
        :param Optional[str] proxy: proxy alias
        :return: None
        """
        proxy.save_elg_log(output_path)

    @lookup_handler.implicit_lookup
    def inject_message(self, message_id, src_module, sap, local_param, dest_module=None, proxy=None):
        """
        send some MTK command for workaround behavior

        :param str message_id: e.g. 'MSG_ID_TST_INJECT_STRING'
        :param str src_module: e.g. 'MOD_DHL'
        :param str sap: e.g. 'INVALID_SAP'
        :param dict local_param: e.g. s{'index': 0, 'string': ''}
        :param Optional[str] dest_module: usually default None
        :param Optional[str] proxy:  proxy alias
        :return: True or False
        :rtype: bool
        """
        return proxy.inject_message(message_id, src_module, dest_module, sap, local_param)

    @lookup_handler.implicit_lookup
    def send_at_command(self, cmd, proxy=None):
        """
        send AT command

        :param str cmd: AT command
        :param Optional[str] proxy:  proxy alias
        :return: True or False
        :rtype: bool
        """
        return proxy.send_at_command(cmd)

    @lookup_handler.implicit_lookup
    def set_log_collector_start_timestamp(self, proxy=None):
        """
        set log collector start timestamp
        store current time as start timestamp which will be applied for all message flows reader
        all message flows will read log from start timestamp at first read

        :param Optional[str] proxy:  proxy alias
        :return: None
        """
        proxy.set_log_collector_start_timestamp()

    @lookup_handler.implicit_lookup
    def read_ota_message_until(self, expected, wait_timeout=5, proxy=None):
        """
        read ota message until expected is found in a timeout

        :param str expected: expected string or regex pattern
        :param Optional[int] wait_timeout: unit is second
        :param Optional[str] proxy: proxy alias
        :return: ota messages
        :rtype: List[str]
        """
        return proxy.read_ota_message_until(expected, wait_timeout)

    @lookup_handler.implicit_lookup
    def read_ota_message_details_until(self, expected, wait_timeout=5, proxy=None):
        """
        read ota message details until expected is found in a timeout

        :param str expected: expected string or regex pattern
        :param Optional[int] wait_timeout: unit is second
        :param Optional[str] proxy: proxy alias
        :return: ota message json string
        :rtype: List[str]
        """
        return proxy.read_ota_message_details_until(expected, wait_timeout)

    @lookup_handler.implicit_lookup
    def read_systrace_until(self, expected, wait_timeout=5, proxy=None):
        """
        read system trace until expected is found in a timeout

        :param str expected: expected string or regex pattern
        :param Optional[int] wait_timeout: unit is second
        :param Optional[str] proxy: proxy alias
        :return: system trace messages
        :rtype: List[str]
        """
        return proxy.read_systrace_until(expected, wait_timeout)

    @lookup_handler.implicit_lookup
    def read_pstrace_until(self, expected, wait_timeout=5, proxy=None):
        """
        read ps trace until expected is found in a timeout

        :param str expected: expected string or regex pattern
        :param Optional[int] wait_timeout: unit is second
        :param Optional[str] proxy: proxy alias
        :return: ps trace messages
        :rtype: List[str]
        """
        return proxy.read_pstrace_until(expected, wait_timeout)

    @lookup_handler.implicit_lookup
    def read_raw_string_until(self, expected, wait_timeout=5, proxy=None):
        """
        read raw string until expected is found in a timeout

        :param str expected: expected string or regex pattern
        :param Optional[int] wait_timeout: unit is second
        :param Optional[str] proxy: proxy alias
        :return: raw strings
        :rtype: List[str]
        """
        return proxy.read_raw_string_until(expected, wait_timeout)

    @lookup_handler.implicit_lookup
    def read_latest_ota_message(self, proxy=None):
        """
        read ota message from last read end

        :param Optional[str] proxy: proxy alias
        :return: ota messages
        :rtype: List[str]
        """
        return proxy.read_latest_ota_message()

    @lookup_handler.implicit_lookup
    def read_latest_ota_message_details(self, proxy=None):
        """
        read ota message details from last read end

        :param Optional[str] proxy: proxy alias
        :return: ota message json string
        :rtype: List[str]
        """
        return proxy.read_latest_ota_message_details()

    @lookup_handler.implicit_lookup
    def read_latest_systrace(self, proxy=None):
        """
        read system trace from last read end

        :param Optional[str] proxy: proxy alias
        :return: system trace messages
        :rtype: List[str]
        """
        return proxy.read_latest_systrace()

    @lookup_handler.implicit_lookup
    def read_latest_pstrace(self, proxy=None):
        """
        read ps trace from last read end

        :param Optional[str] proxy: proxy alias
        :return: ps trace messages
        :rtype: List[str]
        """
        return proxy.read_latest_pstrace()

    @lookup_handler.implicit_lookup
    def read_latest_raw_string(self, proxy=None):
        """
        read raw strings from last read end

        :param Optional[str] proxy: proxy alias
        :return: raw strings
        :rtype: List[str]
        """
        return proxy.read_latest_raw_string()

    def _save_remote_files(self, target_dir):
        logger.debug('start downloading remote logs...')
        try:
            if self._rpc.workspace.is_accessable:
                self._rpc.workspace.collect_remote_files(self._rpc.workspace.log_dir, target_dir)
            else:
                self._rpc.workspace.setup()
                self._rpc.workspace.collect_remote_files(self._rpc.workspace.log_dir, target_dir)
                self._rpc.workspace.teardown()
            logger.debug('downloading remote logs done')
        except Exception as e:
            logger.warning('failed to download files from workspace for {}'.format(e))
